// Bundled sample flights (public/samples, generated by `npm run samples`).
export interface Sample {
  id: string;
  title: string;
  description: string;
  file: string;
  duration: number; // s
}

let manifest: Promise<Sample[]> | null = null;

export function loadSamples(): Promise<Sample[]> {
  manifest ??= fetch("samples/samples.json")
    .then((r) => (r.ok ? r.json() : []))
    .catch(() => []);
  return manifest;
}

export async function fetchSample(s: Sample): Promise<File> {
  const res = await fetch(`samples/${s.file}`);
  if (!res.ok) throw new Error(`sample ${s.file}: HTTP ${res.status}`);
  return new File([await res.blob()], s.file);
}
